from _lib import *
lesson("mixed-conditionals", "Tryby warunkowe", "Mieszane okresy warunkowe", 2,
 "Mieszany okres warunkowy łączy dwie różne płaszczyzny czasowe. Najczęściej: warunek w przeszłości (if + past perfect), a skutek w teraźniejszości (would + bezokolicznik) – albo odwrotnie: stała cecha w teraźniejszości (if + past simple) i skutek w przeszłości (would have + past participle). Oba warunki są nierzeczywiste – opisują coś, co się nie wydarzyło lub nie jest prawdą.",
 "Używamy go, gdy mówimy o żalu, krytyce lub hipotezach typu: 'gdybym wtedy…, teraz…' oraz 'gdybym był innym człowiekiem, wtedy…'. Bardzo przydatny w esejach (argumenty hipotetyczne) i w Part 4.",
 dict(scheme="(1) If + past perfect, would + bezokolicznik  (2) If + past simple, would have + past participle", word_order="If I had taken the job, I would be rich now. / If I were braver, I would have said something.",
      affirmative=["If she had studied medicine, she would be a doctor now.", "If he were more careful, he wouldn't have crashed the car."],
      negative=["If I hadn't missed the bus, I wouldn't be so late now.", "If they didn't trust him, they wouldn't have lent him money."],
      questions=["Would you be happier now if you had stayed in London?", "If you weren't so stubborn, would you have apologised?"]),
 [X("If I had saved more money, I would own a flat now.", "Gdybym oszczędzał więcej, miałbym teraz mieszkanie.", "Przeszła przyczyna → obecny skutek."),
  X("If she hadn't moved abroad, she wouldn't speak three languages.", "Gdyby nie wyjechała za granicę, nie mówiłaby trzema językami.", "Przeszłość (wyjazd) → teraźniejszość (umiejętność)."),
  X("If we had booked earlier, we would be sitting on the beach now.", "Gdybyśmy zarezerwowali wcześniej, siedzielibyśmy teraz na plaży.", "Skutek w formie ciągłej: would be + -ing."),
  X("If he were more organised, he wouldn't have missed the deadline.", "Gdyby był lepiej zorganizowany, nie przegapiłby terminu.", "Stała cecha (teraz) → przeszły skutek."),
  X("If I didn't love my job, I would have left years ago.", "Gdybym nie kochał swojej pracy, odszedłbym lata temu.", "Teraźniejszy stan → przeszła decyzja."),
  X("If you had listened to me, we wouldn't be lost.", "Gdybyś mnie posłuchał, nie zgubilibyśmy się (teraz nie bylibyśmy zgubieni).", "Typowy wyrzut."),
  X("If the government had invested in rail, traffic would be lighter today.", "Gdyby rząd zainwestował w kolej, ruch byłby dziś mniejszy.", "Zdanie typowe dla eseju."),
  X("If she weren't afraid of flying, she would have visited us last summer.", "Gdyby nie bała się latać, odwiedziłaby nas zeszłego lata.", "Were dla wszystkich osób w stylu formalnym."),
  X("If I had been born in Spain, I would probably support Real Madrid.", "Gdybym urodził się w Hiszpanii, pewnie kibicowałbym Realowi.", "Fakt z przeszłości → obecna preferencja."),
  X("If they knew the area, they would have found the hotel easily.", "Gdyby znali okolicę, łatwo znaleźliby hotel.", "Brak wiedzy teraz/ogólnie → przeszła trudność."),
  X("Had I accepted the offer, I would be living in Berlin now.", "Gdybym przyjął ofertę, mieszkałbym teraz w Berlinie.", "Wersja z inwersją (bez if) – formalna.")],
 [C("Mixed vs third conditional", "Third: obie części w przeszłości (would have done). Mixed: jedna część dotyczy teraz.", "Jeśli skutek widać dziś (now, today, still) – mixed."),
  C("Mixed vs second conditional", "Second: obie części teraz/ogólnie (If I had time, I would help).", "Jeśli przyczyna wydarzyła się w konkretnym momencie w przeszłości – mixed z past perfect."),
  C("would be vs would have been", "would be = skutek teraz; would have been = skutek wtedy.", "Słowa now/today sugerują would be.")],
 [W("If I would have studied, I would be a lawyer.", "If I had studied, I would be a lawyer.", "W części z if nie używamy would."),
  W("If I had taken the job, I would have been rich now.", "If I had taken the job, I would be rich now.", "'Now' wskazuje na skutek w teraźniejszości."),
  W("If she was more patient, she wouldn't have shouted.", "If she were more patient, she wouldn't have shouted.", "W stylu formalnym 'were' (was jest potoczne, ale na egzaminie bezpieczniej were)."),
  W("If I didn't miss the train, I wouldn't be late.", "If I hadn't missed the train, I wouldn't be late.", "Spóźnienie na pociąg to zdarzenie z przeszłości → past perfect.")],
 ["Zamiast would w skutku można użyć could/might: If I had learnt to drive, I could take you there now.",
  "Część z if może stać na końcu – wtedy bez przecinka: I would be rich now if I had taken the job.",
  "But for + rzeczownik zastępuje warunek: But for his help, I would be in trouble now."],
 [dict(en="Were it not for the scholarship, she would never have studied abroad.", pl="Gdyby nie stypendium, nigdy nie studiowałaby za granicą.", note="Inwersja z were – bardzo formalnie."),
  dict(en="Had the warnings been heeded, the city would not be facing a crisis today.", pl="Gdyby posłuchano ostrzeżeń, miasto nie stałoby dziś w obliczu kryzysu.", note="Strona bierna + inwersja + skutek teraz."),
  dict(en="If it hadn't been for the pandemic, remote work would still be rare.", pl="Gdyby nie pandemia, praca zdalna wciąż byłaby rzadkością.", note="If it hadn't been for = gdyby nie (w przeszłości).")],
 [G("If I ___ (take) that job in 2019, I would be a manager now.", ["had taken"], "Przeszłe zdarzenie → past perfect."),
  G("If she weren't so shy, she ___ (speak) at yesterday's meeting.", ["would have spoken"], "Skutek w przeszłości: would have + past participle."),
  M("If we had left earlier, we ___ stuck in traffic now.", ["wouldn't be", "wouldn't have been", "won't be", "hadn't been"], "wouldn't be", "'Now' → skutek teraz.", {"wouldn't have been": "To skutek w przeszłości, a zdanie mówi o 'now'.", "won't be": "Pierwszy okres – realny, a tu sytuacja jest nierzeczywista.", "hadn't been": "Past perfect należy do części z if."}),
  G("If he ___ (not / be) so lazy, he would have passed the exam.", ["weren't", "were not", "wasn't", "was not"], "Stała cecha teraz → past simple."),
  G("I would be fluent in Italian now if I ___ (stay) in Rome.", ["had stayed"], "Kolejność odwrócona, logika ta sama."),
  K("I didn't go to the party, so I don't know her.", "WOULD", "If I had gone to the party, I ___ her.", ["would know"], "Przeszłość → teraz: would know."),
  E("If I would have known, I would tell you now.", ["If I had known, I would tell you now.", "had known"], "W zdaniu z if nie ma would."),
  T("Gdybym nie złamał nogi, biegałbym teraz maraton.", ["If I hadn't broken my leg, I would be running a marathon now.", "If I had not broken my leg, I would be running a marathon now.", "If I hadn't broken my leg, I would run a marathon now."], "Past perfect + would be + -ing.")],
 [G("If they ___ (invest) in solar power years ago, their bills would be lower today.", ["had invested"], "Lata temu → past perfect."),
  G("If I were you, I ___ (accept) the offer last week.", ["would have accepted"], "Rada dotycząca przeszłości."),
  K("She is not tall, so she wasn't chosen for the team.", "TALLER", "If she ___ chosen for the team.", ["were taller, she would have been", "was taller, she would have been"], "Cecha teraz → przeszły skutek w stronie biernej."),
  K("We are lost because we didn't take a map.", "HAD", "If we ___ wouldn't be lost.", ["had taken a map, we"], "Past perfect w warunku, skutek teraz."),
  M("___ the bus, I would be at home by now.", ["Had I not missed", "If I didn't miss", "Would I not miss", "Hadn't I missed"], "Had I not missed", "Inwersja: Had + podmiot + not + past participle.", {"If I didn't miss": "Past simple nie oddaje przeszłego zdarzenia.", "Would I not miss": "Would nie wprowadza warunku.", "Hadn't I missed": "W inwersji not stoi po podmiocie: Had I not."}),
  T("Gdyby był bardziej ostrożny, nie straciłby wczoraj portfela.", ["If he were more careful, he wouldn't have lost his wallet yesterday.", "If he was more careful, he wouldn't have lost his wallet yesterday.", "If he were more careful, he would not have lost his wallet yesterday."], "Cecha teraz → skutek w przeszłości.")])
